import inspect
import re
import ast
import base64
import pytest


def _get_source():
    return inspect.getsource(call_api_v3)


def _extract_string_literals(src: str):
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return []
    lits = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            lits.append(node.value)
    return lits


def test_cwe798_uses_environment_variable_for_api_key(monkeypatch):
    src = _get_source()
    assert re.search(r"os\.environ\.get\(\s*['\"]API_KEY['\"]\s*\)", src), "API key should be sourced from environment variables"
    assert "Bearer" in src, "Authorization header should be constructed from env-sourced token"


def test_cwe798_no_obvious_hardcoded_secret_literals_in_source():
    src = _get_source()
    literals = _extract_string_literals(src)

    suspicious_patterns = [
        r"sk-[A-Za-z0-9]{10,}",                       # common API key prefix
        r"AKIA[0-9A-Z]{16}",                           # AWS access key id
        r"AIza[0-9A-Za-z\-_]{20,}",                    # Google API key
        r"ghp_[A-Za-z0-9]{20,}",                       # GitHub token
        r"xox[baprs]-[A-Za-z0-9-]{10,}",               # Slack tokens
        r"-----BEGIN (RSA|EC|OPENSSH) PRIVATE KEY-----",
        r"(?i)\b(password|passwd|secret|api[_-]?key|token)\b\s*[:=]\s*.+",
    ]

    for s in literals:
        for pat in suspicious_patterns:
            assert not re.search(pat, s), f"Potential hardcoded credential detected in string literal: {s!r}"


def test_cwe798_no_default_credentials_in_source():
    src = _get_source().lower()
    defaults = [
        "admin:admin",
        "root:root",
        "admin/admin",
        "root/root",
        "username=admin",
        "password=admin",
        "password=root",
    ]
    for d in defaults:
        assert d not in src, f"Default credential pattern should not appear in source: {d}"


def test_cwe798_no_base64_encoded_credentials_in_source():
    src = _get_source()
    literals = _extract_string_literals(src)

    def looks_like_base64(s: str) -> bool:
        if len(s) < 16 or len(s) % 4 != 0:
            return False
        if not re.fullmatch(r"[A-Za-z0-9+/=]+", s):
            return False
        return True

    for s in literals:
        if looks_like_base64(s):
            try:
                decoded = base64.b64decode(s, validate=True).decode("utf-8", errors="ignore")
            except Exception:
                continue
            assert not re.search(r"(?i)\b(admin|root)\b\s*[:/]\s*\b(admin|root)\b", decoded), "Base64-encoded default credentials detected"
            assert not re.search(r"(?i)\b(password|secret|api[_-]?key|token)\b", decoded), "Base64-encoded secret-like content detected"


def test_cwe798_runtime_rejects_missing_api_key(monkeypatch):
    monkeypatch.delenv("API_KEY", raising=False)
    with pytest.raises(ValueError):
        call_api_v3("https://example.com/api")

