import operator
PHYSICS_OPS = {ast.Add: operator.add, ast.Sub: operator.sub,
               ast.Mult: operator.mul, ast.Div: operator.truediv}
def resolve_physics_equation(equation_str):
    """Resolve physics equation safely using AST."""
    def _calculate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            if type(node.op) not in PHYSICS_OPS:
                raise ValueError("Unsupported operation")
            return PHYSICS_OPS[type(node.op)](_calculate(node.left), _calculate(node.right))
        raise ValueError("Invalid equation")
    return _calculate(ast.parse(equation_str, mode='eval').body)

