import inspect
import ast
import re


def _get_requests_calls(fn):
    src = inspect.getsource(fn)
    tree = ast.parse(src)
    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == "requests":
                if node.func.attr in ("get", "post", "request"):
                    calls.append(node)
    return calls, tree


def _get_kw(call_node, name):
    for kw in call_node.keywords or []:
        if kw.arg == name:
            return kw.value
    return None


def _is_bool_const(node, value):
    return isinstance(node, ast.Constant) and node.value is value


def _contains_unverified_ssl_usage(tree):
    patterns = {
        ("ssl", "_create_unverified_context"),
        ("ssl", "CERT_NONE"),
    }
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name):
                if (node.func.value.id, node.func.attr) in patterns:
                    return True
        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name):
            if (node.value.id, node.attr) in patterns:
                return True
    return False


def _contains_hostname_bypass(tree):
    # Look for check_hostname = False anywhere in the module/function source
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for tgt in node.targets:
                if isinstance(tgt, ast.Attribute) and tgt.attr == "check_hostname":
                    if _is_bool_const(node.value, False):
                        return True
        if isinstance(node, ast.Call):
            # context.check_hostname = False could also appear via setattr(...)
            if isinstance(node.func, ast.Name) and node.func.id == "setattr":
                if len(node.args) >= 3:
                    if isinstance(node.args[1], ast.Constant) and node.args[1].value == "check_hostname":
                        if _is_bool_const(node.args[2], False):
                            return True
    return False


def _contains_http_downgrade(tree):
    # Detect usage that forces http:// (string literals or replace('https://','http://') style)
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            if "http://" in node.value and "https://" not in node.value:
                return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr == "replace" and len(node.args) >= 2:
                a0, a1 = node.args[0], node.args[1]
                if isinstance(a0, ast.Constant) and isinstance(a1, ast.Constant):
                    if a0.value == "https://" and a1.value == "http://":
                        return True
    return False


