def _extract_url_and_verify_from_source(func):
    src = inspect.getsource(func)
    tree = ast.parse(src)
    url = None
    verify = None

    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr in ("put", "post", "get", "request"):
                if node.args:
