import pytest
import builtins
from pathlib import Path


def _patch_open_to_guard_base(monkeypatch, base_dir="/templates"):
    real_open = builtins.open

    def guarded_open(path, *args, **kwargs):
        p = Path(path)
        try:
            rp = p.resolve()
        except Exception:
            rp = p
        base = Path(base_dir).resolve()
        if not str(rp).startswith(str(base)):
            raise PermissionError(f"Attempted open outside base: {rp}")
        return real_open(path, *args, **kwargs)

    monkeypatch.setattr(builtins, "open", guarded_open)


def test_path_traversal_parent_segments_rejected(monkeypatch):
    _patch_open_to_guard_base(monkeypatch, "/templates")
    payloads = [
        "../../../etc/passwd",
        ".." + "/.." * 8 + "/etc/passwd",
        "....//....//etc/passwd",
    ]
