import time
import pytest


class SlowStream:
    def __init__(self, chunk=b"a", delay_per_chunk=0.001):
        self.chunk = chunk
        self.delay = delay_per_chunk
        self.calls = 0

    def read(self, n=-1):
        self.calls += 1
        time.sleep(self.delay)
        return self.chunk if n != 0 else b""


class InfiniteStream:
    def __init__(self, chunk=b"a"):
        self.chunk = chunk
        self.calls = 0

    def read(self, n=-1):
        self.calls += 1
        if n is None or n < 0:
            while True:
                pass
        return self.chunk * n


class HugeAllocStream:
    def __init__(self, multiplier=50):
        self.multiplier = multiplier
        self.calls = 0

    def read(self, n=-1):
        self.calls += 1
        if n is None or n < 0:
            n = MAX_TEMPLATE_SIZE + 1
        return b"a" * (n * self.multiplier)


def test_cwe400_enforces_size_limit_boundary_and_rejects_oversize():
    class ByteStream:
        def __init__(self, data):
            self.data = data
            self.calls = 0

        def read(self, n=-1):
            self.calls += 1
            if n is None or n < 0:
                return self.data
            return self.data[:n]

    ok_stream = ByteStream(b"a" * MAX_TEMPLATE_SIZE)
    data = load_template_file(ok_stream)
    assert len(data) == MAX_TEMPLATE_SIZE
    assert ok_stream.calls == 1

    too_big_stream = ByteStream(b"a" * (MAX_TEMPLATE_SIZE + 1))
    with pytest.raises(ValueError):
