def _get_source(fn):
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""


def _find_requests_call_kwargs(source):
    try:
        tree = ast.parse(source)
    except Exception:
        return []

    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func
            name = None
            if isinstance(func, ast.Attribute):
                name = func.attr
            elif isinstance(func, ast.Name):
                name = func.id
            if name in {"get", "post", "put", "delete", "request"}:
                kw = {}
                for k in node.keywords or []:
                    if k.arg is None:
                        continue
                    kw[k.arg] = k.value
                calls.append((name, kw))
    return calls


def _is_true(node):
    return isinstance(node, ast.Constant) and node.value is True


def _is_false(node):
    return isinstance(node, ast.Constant) and node.value is False


def _is_str_const(node, s):
    return isinstance(node, ast.Constant) and isinstance(node.value, str) and node.value == s


def _contains_any_url_literal_http(source):
    # Catch direct "http://..." literals anywhere in the function
    return re.search(r'(["\'])http://', source) is not None


