        "https://evil.example/steal",
        "bob\r\nHost: evil.example\r\n\r\n",
        "../admin",
        "alice?redirect=http://evil.example",
        "alice#http://evil.example",
        "alice%0d%0aHost%3a%20evil.example",
    ]

