def _extract_requests_get_calls(fn):
    src = inspect.getsource(fn)
    tree = ast.parse(src)
    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == "requests" and node.func.attr == "get":
                calls.append(node)
    return calls, src


def _get_kwarg(call_node, name):
    for kw in call_node.keywords:
        if kw.arg == name:
            return kw.value
    return None


def _is_bool_const(node, val):
    return isinstance(node, ast.Constant) and node.value is val


def test_cwe295_verify_true_enforced_in_request():
    calls, _ = _extract_requests_get_calls(perform_cb0216)
    assert calls, "No requests.get call found; cannot verify certificate validation behavior"
    for call in calls:
        verify_node = _get_kwarg(call, "verify")
        assert verify_node is not None, "TLS certificate verification must be explicitly enabled via verify=True"
        assert _is_bool_const(verify_node, True), "Improper certificate validation: verify must be True (not False/None/variable)"


