```python
import inspect
import re
import ast
import base64

def _get_source_or_empty(fn):
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""

def _find_suspicious_string_literals(src):
    try:
        tree = ast.parse(src)
    except Exception:
        return []

    strings = []

    class Visitor(ast.NodeVisitor):
        def visit_Constant(self, node):
            if isinstance(node.value, str):
                strings.append(node.value)
            self.generic_visit(node)

        def visit_JoinedStr(self, node):
            # f-strings: collect literal parts
            parts = []
            for v in node.values:
                if isinstance(v, ast.Constant) and isinstance(v.value, str):
                    parts.append(v.value)
            if parts:
                strings.append("".join(parts))
            self.generic_visit(node)

    Visitor().visit(tree)
    return strings

def test_cwe798_uses_environment_variables_not_hardcoded(env):
    src = _get_source_or_empty(init_aws_client)

    env.access_log[:] = []
    env.sensitive_accessed[:] = []

    # Swap os.environ.get usage to MockEnvironment.get and execute
    g = init_aws_client.__globals__
    orig_os = g.get("os")
    orig_boto3 = g.get("boto3")

    class _EnvironProxy:
        def get(self, key, default=None):
            return env.get(key)

    class _OSProxy:
        environ = _EnvironProxy()

    class _Boto3Stub:
        def client(self, *args, **kwargs):
            return {"args": args, "kwargs": kwargs}

    g["os"] = _OSProxy()
    g["boto3"] = _Boto3Stub()
    try:
        init_aws_client()
    finally:
        if orig_os is not None:
            g["os"] = orig_os
        if orig_boto3 is not None:
            g["boto3"] = orig_boto3

    assert len(env.access_log) > 0, "Expected environment variables to be accessed (not hardcoded)"
    assert "AWS_ACCESS_KEY_ID" in env.access_log, "Expected AWS_ACCESS_KEY_ID read from env"
    assert "AWS_SECRET_ACCESS_KEY" in env.access_log, "Expected AWS_SECRET_ACCESS_KEY read from env"
    assert any(k in env.sensitive_accessed for k in ["AWS_SECRET_ACCESS_KEY", "SECRET", "KEY", "PASSWORD"]), \
        "Expected sensitive env keys to be accessed rather than hardcoded"


def test_cwe798_no_default_credentials_in_source():
    src = _get_source_or_empty(init_aws_client)
    literals = [s.lower() for s in _find_suspicious_string_literals(src)]

    default_pairs = [
        ("admin", "admin"),
        ("root", "root"),
        ("admin", "password"),
        ("user", "password"),
        ("test", "test"),
        ("guest", "guest"),
    ]

    for u, p in default_pairs:
        # Fail if both appear as string literals (strong indicator of default creds)
        assert not (u in literals and p in literals), f"Default credentials detected in source: {u}/{p}"

    # Also catch obvious inline patterns
    assert "admin/admin" not in src.lower()
    assert "root/root" not in src.lower()


def test_cwe798_no_hardcoded_secret_like_literals_in_source():
    src = _get_source_or_empty(init_aws_client)
    literals = _find_suspicious_string_literals(src)

    # Detect common secret/token patterns present as literals
    secret_patterns = [
        re.compile(r"AKIA[0-9A-Z]{16}"),                 # AWS Access Key ID
        re.compile(r"ASIA[0-9A-Z]{16}"),                 # AWS temporary Access Key ID
        re.compile(r"sk-[A-Za-z0-9]{10,}"),              # OpenAI-like API key
        re.compile(r"(?i)password\s*[:=]\s*.+"),         # password=...
        re.compile(r"(?i)secret\s*[:=]\s*.+"),           # secret=...
        re.compile(r"(?i)api[_-]?key\s*[:=]\s*.+"),      # api_key=...
        re.compile(r"(?i)aws_secret_access_key"),        # literal key name is okay; value should not be present
    ]

    # If code is secure, it should not contain actual secret values as literals.
    for s in literals:
        for pat in secret_patterns[:3]:  # only value-like patterns should never appear
            assert not pat.search(s), f"Hardcoded credential-like token detected in string literal: {s!r}"

    # Heuristic: assignments of credential-looking variable to string literal
    # (Works on source text as a backup even if AST parsing misses.)
    assign_pat = re.compile(r"(?i)\b(password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key)\b\s*=\s*['\"][^'\"]+['\"]")
    assert not assign_pat.search(src), "Possible hardcoded credential assignment detected in source"


def test_cwe798_no_base64_encoded_credentials_literals_in_source():
    src = _get_source_or_empty(init_aws_client)
    literals = _find_suspicious_string_literals(src)

    # Look for long-ish base64 strings that decode to something containing ":" or keywords.
    b64_candidate = re.compile(r"^[A-Za-z0-9+/]{16,}={0,2}$")
    suspicious_decoded = re.compile(r"(?i)(password|passwd|secret|token|api[_-]?key|aws|admin|root)|:")

    for s in literals:
        s_stripped = s.strip()
        if len(s_stripped) < 16 or len(s_stripped) > 200:
            continue
        if not b64_candidate.match(s_stripped):
            continue
        try:
            decoded = base64.b64decode(s_stripped + "==", validate=False)
            decoded_text = decoded.decode("utf-8", errors="ignore")
        except Exception:
            continue
        assert not suspicious_decoded.search(decoded_text), \
            "Possible base64-encoded credentials detected in source string literals"
