import time
import pytest


class _SlowStream:
    def __init__(self, size, chunk=1024, delay_per_chunk=0.0):
        self.size = size
        self.chunk = chunk
        self.delay = delay_per_chunk
        self.read_so_far = 0

    def read(self, n=-1):
        if n is None or n < 0:
            n = self.size - self.read_so_far
        to_read = min(n, self.size - self.read_so_far)
        if to_read <= 0:
            return b""

        remaining = to_read
        out = bytearray()
        while remaining > 0:
            if self.delay:
                time.sleep(self.delay)
            c = min(self.chunk, remaining)
            out.extend(b"A" * c)
            remaining -= c
            self.read_so_far += c
        return bytes(out)


class _InfiniteStream:
    def __init__(self, chunk=1024):
        self.chunk = chunk
        self.total_read = 0

    def read(self, n=-1):
        if n is None or n < 0:
            n = self.chunk
        self.total_read += n
        return b"A" * n


class _HugeClaimStream:
    def __init__(self):
        self.calls = 0

    def read(self, n=-1):
        self.calls += 1
        if n is None or n < 0:
            n = MAX_CSV_SIZE + 1
        return b"A" * n

    def __len__(self):
        return 2**63 - 1


