def _parse_rsa_pem_key_size(pem: str) -> int:
    m = re.search(r"BEGIN RSA PRIVATE KEY", pem)
    if not m:
        # PKCS#8 "BEGIN PRIVATE KEY" still contains RSA; parse by importing if available
        pass
    try:
