import inspect
import pytest


def _get_function_source(fn):
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""


def _extract_string_literals_from_source(source):
    vals = []
    try:
        tree = ast.parse(source)
    except Exception:
        return vals
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            vals.append(node.value)
    return vals


def _looks_like_secret(s):
    s_stripped = s.strip()
    if not s_stripped:
        return False

    # Obvious default creds or patterns
    low = s_stripped.lower()
    if low in {"admin", "password", "admin123", "root", "toor"}:
        return True
    if low in {"admin:admin", "root:root", "admin/admin", "root/root"}:
        return True

    # API key/token-like patterns
    if re.search(r"\bsk-[A-Za-z0-9]{10,}\b", s_stripped):
        return True
    if re.search(r"\bAKIA[0-9A-Z]{16}\b", s_stripped):  # AWS access key id pattern
        return True
    if re.search(r"\bghp_[A-Za-z0-9]{20,}\b", s_stripped):  # GitHub token pattern
        return True
    if re.search(r"\bBearer\s+[A-Za-z0-9\-\._~\+\/]+=*\b", s_stripped):
        return True

    # Long random-ish strings (heuristic)
    if len(s_stripped) >= 24 and re.fullmatch(r"[A-Za-z0-9+/=_\-\.~]+", s_stripped):
        return True

    return False


def _is_base64_like(s):
    s = s.strip()
    if len(s) < 16:
        return False
    if len(s) % 4 != 0:
        return False
    return re.fullmatch(r"[A-Za-z0-9+/]+={0,2}", s) is not None


def _decoded_base64_looks_like_creds(decoded_bytes):
    try:
        decoded = decoded_bytes.decode("utf-8", errors="ignore")
    except Exception:
        return False
    low = decoded.lower()
    if "api" in low and "key" in low:
        return True
    if "secret" in low or "password" in low or "passwd" in low:
        return True
    if re.search(r"\b(admin|root)\b\s*[:/]\s*\b(admin|root|password|admin123)\b", low):
        return True
    if re.search(r"\bsk-[A-Za-z0-9]{10,}\b", decoded):
        return True
    return False


