import ast
import base64
import os


def _extract_string_literals(func):
    src = inspect.getsource(func)
    tree = ast.parse(src)

    literals = []

    class V(ast.NodeVisitor):
        def visit_Constant(self, node):
            if isinstance(node.value, str):
                literals.append(node.value)
            self.generic_visit(node)

        def visit_JoinedStr(self, node):
            # Collect f-string literal parts
            for v in node.values:
                if isinstance(v, ast.Constant) and isinstance(v.value, str):
                    literals.append(v.value)
            self.generic_visit(node)

    V().visit(tree)
    return literals


def _looks_like_secret(s):
    if not s or len(s) < 4:
        return False

    low = s.lower()

    # Default creds patterns
    if low in {"admin", "root", "password", "admin123"}:
        return True
    if "admin:admin" in low or "root:root" in low:
        return True

    # Token-like patterns
    if re.search(r"\bsk-[A-Za-z0-9]{10,}\b", s):
        return True
    if re.search(r"\b(xox[baprs]-[A-Za-z0-9-]{10,})\b", s):
        return True
    if re.search(r"\bAKIA[0-9A-Z]{16}\b", s):
        return True

    # Generic high-entropy-ish API key hints
    if re.search(r"\b(api[_-]?key|secret|token|passwd|password)\b", low) and re.search(
        r"[A-Za-z0-9+/=_-]{8,}", s
    ):
        return True

    return False


def _looks_like_base64_secret(s):
    if not s or len(s) < 8:
        return False
    if len(s) % 4 != 0:
        return False
    if not re.fullmatch(r"[A-Za-z0-9+/=]+", s):
        return False
    try:
        decoded = base64.b64decode(s, validate=True)
    except Exception:
        return False
    try:
        text = decoded.decode("utf-8", errors="ignore")
    except Exception:
        return False
    low = text.lower()
    if any(k in low for k in ["password", "passwd", "secret", "token", "api_key", "apikey", "authorization"]):
        return True
    if "admin:" in low or "root:" in low:
        return True
    return False


