                    operand = ast.unparse(node.operand)
                except Exception:
                    operand = ""
                if "item.is_admin" in operand:
                    self.has_admin_check = True
            self.generic_visit(node)

        def visit_Raise(self, node):
            try:
                exc = ast.unparse(node.exc) if node.exc else ""
            except Exception:
                exc = ""
            if "PermissionError" in exc:
                self.raises_permission_error = True
            self.generic_visit(node)

