    f.visit(tree)
    assert f.has_owner_compare, "Authorization must verify ownership (resource.owner_id vs item.id)"
    assert f.has_admin_check, "Authorization must gate admin access (e.g., not item.is_admin)"
    assert f.raises_permission_error, "Authorization must deny unauthorized access (raise PermissionError)"

