import os
import re
import ast
import base64
import inspect
import pytest


def _scan_for_hardcoded_secrets_in_source(src: str):
    findings = []

    # Direct assignment patterns
    assign_re = re.compile(
        r"""(?i)\b(password|passwd|pwd|secret|api[_-]?key|token)\b\s*=\s*(['"])(?P<val>.+?)\2"""
    )
    for m in assign_re.finditer(src):
        findings.append(("direct_assignment", m.group(1), m.group("val")))

    # Default credential pairs
    default_pairs = [
        ("admin", "admin"),
        ("root", "root"),
        ("admin", "password"),
        ("administrator", "administrator"),
        ("user", "user"),
    ]
    for u, p in default_pairs:
        if re.search(rf"""(['"]){re.escape(u)}\1\s*,\s*(['"]){re.escape(p)}\2""", src, re.I):
            findings.append(("default_pair_tuple", f"{u}/{p}", None))
        if re.search(rf"""{re.escape(u)}\s*/\s*{re.escape(p)}""", src, re.I):
            findings.append(("default_pair_slash", f"{u}/{p}", None))

    # Common key formats (e.g., sk-..., AKIA..., ghp_..., xoxb-...)
    key_patterns = [
        (r"\bsk-[A-Za-z0-9]{10,}\b", "openai_like_sk"),
        (r"\bAKIA[0-9A-Z]{16}\b", "aws_access_key_id"),
        (r"\bghp_[A-Za-z0-9]{20,}\b", "github_pat"),
        (r"\bxox[baprs]-[A-Za-z0-9-]{10,}\b", "slack_token"),
    ]
    for pat, name in key_patterns:
        if re.search(pat, src):
            findings.append(("key_pattern", name, None))

    # Base64-encoded suspicious strings (decoded contains sensitive keywords or looks like user:pass)
    b64_re = re.compile(r"""(['"])(?P<b64>(?:[A-Za-z0-9+/]{16,}={0,2}))\1""")
    for m in b64_re.finditer(src):
        b64s = m.group("b64")
        if len(b64s) % 4 != 0:
            continue
        try:
            decoded = base64.b64decode(b64s).decode("utf-8", errors="ignore")
        except Exception:
            continue
        if (
            re.search(r"(?i)\b(password|secret|token|api[_-]?key)\b", decoded)
            or re.search(r"^[^:\s]{1,64}:[^\s]{1,128}$", decoded)
        ):
            findings.append(("base64_secret", decoded, b64s))

    return findings


