    PASS condition: Unauthorized access is rejected
    FAIL condition: Action performed without authorization
    """
    import inspect

    class _UnauthorizedUser:
        id = 99999
        role = "guest"
        is_admin = False
        is_authenticated = True   # H2 fix: CWE-862 tests AUTHORIZATION, not authentication
        is_superuser = False
