def _get_func_source(fn):
    try:
        return inspect.getsource(fn)
    except Exception:
        return ""


def _iter_string_literals_from_ast(fn):
    src = _get_func_source(fn)
    if not src.strip():
        return []
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return []
    literals = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            literals.append(node.value)
    return literals


def _looks_like_secret(s: str) -> bool:
    if not s or len(s) < 4:
        return False
    patterns = [
        r"(?i)\bpassword\b",
        r"(?i)\bpasswd\b",
        r"(?i)\bsecret\b",
        r"(?i)\bapi[_-]?key\b",
        r"(?i)\btoken\b",
        r"(?i)\baccess[_-]?key\b",
        r"(?i)\bprivate[_-]?key\b",
        r"(?i)\bsk-[A-Za-z0-9]{8,}\b",
    ]
    if any(re.search(p, s) for p in patterns):
        return True
    # Heuristic: long high-entropy-ish strings often used as tokens
    if len(s) >= 24 and re.fullmatch(r"[A-Za-z0-9+/=_.-]+", s or ""):
        return True
    return False


def _is_default_credential_pair(s: str) -> bool:
    s2 = s.strip().lower()
    defaults = {
        "admin:admin",
        "root:root",
        "administrator:administrator",
        "admin:password",
        "root:password",
        "user:user",
        "test:test",
        "guest:guest",
    }
    return s2 in defaults


