import inspect
import ast


def _ast_contains_call(func, module_name, attr_names):
    src = inspect.getsource(func)
    tree = ast.parse(src)

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            f = node.func
            # module.attr(...)
            if isinstance(f, ast.Attribute) and f.attr in attr_names and isinstance(f.value, ast.Name):
                if f.value.id == module_name:
                    return True
            # direct attr imported: attr(...)
            if isinstance(f, ast.Name) and f.id in attr_names:
                return True
    return False


