    assert _ast_contains_call(
        generate_api_lot_number, "secrets", {"token_urlsafe", "token_hex", "token_bytes"}
    ), "Security-sensitive token generation must use secrets.* CSPRNG"
    assert not _ast_contains_call(
        generate_api_lot_number, "random", {"random", "randint", "choice", "choices", "randrange", "getrandbits"}
    ), "Weak PRNG detected: random.* should not be used for API tokens"


