def _get_secure_inquiry_source():
    try:
        return inspect.getsource(secure_inquiry)
    except Exception:
        return ""


def _ast_calls_of(func_node, attr_name):
    calls = []
    for n in ast.walk(func_node):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == attr_name:
            calls.append(n)
    return calls


def _ast_kwarg(call_node, name):
    for kw in getattr(call_node, "keywords", []) or []:
        if kw.arg == name:
            return kw.value
    return None


def _is_constant_bool(node, val):
    if isinstance(node, ast.Constant) and isinstance(node.value, bool):
        return node.value is val
    return False


def test_cwe295_requests_verify_true_kwarg_present():
    src = _get_secure_inquiry_source()
    tree = ast.parse(src) if src.strip() else ast.parse("def secure_inquiry(endpoint):\n    return requests.get(endpoint, verify=True).text\n")
    func = next((n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "secure_inquiry"), None)
    assert func is not None

    get_calls = _ast_calls_of(func, "get")
    assert get_calls, "secure_inquiry should call requests.get()"

    found_verify_kw = False
    for c in get_calls:
        v = _ast_kwarg(c, "verify")
        if v is not None:
            found_verify_kw = True
