import time
import pytest


class SlowLargeReader:
    def __init__(self, total_size, chunk_size=8192, per_chunk_delay=0.0):
        self.total_size = total_size
        self.chunk_size = chunk_size
        self.per_chunk_delay = per_chunk_delay
        self.pos = 0

    def read(self, n=-1):
        if n is None or n < 0:
            n = self.total_size - self.pos
        remaining = self.total_size - self.pos
        to_read = min(n, remaining)
        if to_read <= 0:
            return b""
        if self.per_chunk_delay:
            time.sleep(self.per_chunk_delay)
        self.pos += to_read
        return b"A" * to_read


class InfiniteReader:
    def __init__(self, per_read_delay=0.0):
        self.per_read_delay = per_read_delay

    def read(self, n=-1):
