                        if _is_string(kw.value) and _looks_like_secret(kw.value.value):
                            suspicious_literals.append((kw.arg, kw.value.value))
            self.generic_visit(node)

        def visit_Assign(self, node):
            for t in node.targets:
                if isinstance(t, ast.Name) and t.id.lower() in ("password", "passwd", "api_key", "apikey", "secret", "token"):
                    if _is_string(node.value) and _looks_like_secret(node.value.value):
