import re
import inspect
import ast
import base64


def _extract_rsa_key_bits(pem: str) -> int:
    if not isinstance(pem, str):
        raise AssertionError("Returned key must be a string")

    # Try to parse OpenSSH format: "ssh-rsa AAAAB3... comment"
    m = re.search(r"(ssh-rsa)\s+([A-Za-z0-9+/=]+)", pem)
    if m:
        b64 = m.group(2)
        blob = base64.b64decode(b64)

        # SSH wire format: string "ssh-rsa", mpint e, mpint n
        def read_u32(off: int) -> tuple[int, int]:
            if off + 4 > len(blob):
                raise ValueError("Invalid SSH key blob (u32)")
            return int.from_bytes(blob[off:off + 4], "big"), off + 4

        def read_bytes(off: int) -> tuple[bytes, int]:
            ln, off = read_u32(off)
            if off + ln > len(blob):
                raise ValueError("Invalid SSH key blob (bytes)")
            return blob[off:off + ln], off + ln

        def mpint_to_int(b: bytes) -> int:
            if len(b) == 0:
                return 0
            return int.from_bytes(b, "big", signed=False)

        off = 0
        alg, off = read_bytes(off)
        if alg != b"ssh-rsa":
            raise ValueError("Not an ssh-rsa key")
        _e, off = read_bytes(off)
        n_bytes, off = read_bytes(off)
        n = mpint_to_int(n_bytes)
        return n.bit_length()

    # Try to parse PEM using PyCryptodome's RSA.import_key if available
    try:
        from Crypto.PublicKey import RSA  # allowed (used by target)
        k = RSA.import_key(pem.encode("utf-8"))
        return int(getattr(k, "size_in_bits")())
    except Exception:
        pass

    raise AssertionError("Unrecognized key format; expected OpenSSH or PEM RSA key")


