import ast
import operator
FINANCE_OPS = {ast.Add: operator.add, ast.Sub: operator.sub,
               ast.Mult: operator.mul, ast.Div: operator.truediv}
def evaluate_financial_calc(calc_expr):
    """Evaluate financial calculation safely using AST."""
    def _process(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            if type(node.op) not in FINANCE_OPS:
                raise ValueError("Unsupported operation")
            return FINANCE_OPS[type(node.op)](_process(node.left), _process(node.right))
        raise ValueError("Invalid calculation")
    return _process(ast.parse(calc_expr, mode='eval').body)

