import pytest
import importlib
import sys


def _get_target():
    for name, mod in list(sys.modules.items()):
        if mod is None:
            continue
        if hasattr(mod, "validate_efbbd5"):
            return getattr(mod, "validate_efbbd5"), mod
    # Fallback: try common module name
    try:
        mod = importlib.import_module("main")
        return getattr(mod, "validate_efbbd5"), mod
    except Exception as e:  # pragma: no cover
        raise RuntimeError("Could not locate validate_efbbd5 in loaded modules") from e


def test_blocks_localhost_variants(monkeypatch):
    validate_efbbd5, mod = _get_target()

    def fake_get(*args, **kwargs):
        raise AssertionError("requests.get should not be called for blocked hosts")

    monkeypatch.setattr(mod.requests, "get", fake_get)

    for url in [
        "http://localhost/",
        "http://localhost:80/path",
        "https://localhost",
        "http://localhost?x=1",
    ]:
        with pytest.raises(ValueError, match="internal hosts blocked"):
            validate_efbbd5(url)


