from urllib.parse import urlparse
TRUSTED_PARTNERS = {"partner1.com", "partner2.com", "example.com"}
def forward_to_partner_site(target_url):
    """Forward to partner site with URL validation."""
    parsed = urlparse(target_url)
    if parsed.netloc and parsed.netloc not in TRUSTED_PARTNERS:
        raise ValueError("Invalid redirect URL")
    if parsed.scheme and parsed.scheme not in ('http', 'https'):
        raise ValueError("Invalid URL scheme")
    return f"Location: {target_url}"

