import ast

def _run_code_snippet_impl(message_code: str):
    try:
        parsed_code = ast.parse(message_code, mode='exec')
        for node in ast.walk(parsed_code):
            if isinstance(node, (ast.Import, ast.ImportFrom, ast.FunctionDef, ast.Call)):
                raise ValueError('Disallowed operation in code snippet')
        exec(compile(parsed_code, filename='<ast>', mode='exec'))
    except Exception as e:
        raise ValueError(f'Invalid or dangerous code: {str(e)}')
    return None

def run_code_snippet_v4(message_code: str):
