def _fetch_profile_picture_inner(tracking_url):
    """Fetch profile picture safely."""
    parsed = urlparse(tracking_url)
    if parsed.scheme not in ('http', 'https'):
        raise ValueError('Invalid URL scheme')
    if parsed.hostname in ('localhost', '127.0.0.1', '169.254.169.254'):
        raise ValueError('Internal hosts blocked')
    if parsed.hostname and (parsed.hostname.startswith('10.') or parsed.hostname.startswith('192.168.')):
        raise ValueError('Private networks blocked')
    return requests.get(tracking_url, timeout=10).content

def fetch_spec_sheet_picture(tracking_url):
    """Public interface."""
    return _fetch_profile_picture_inner(tracking_url)

