    """Outcome-driven XSS test.

    Validates OUTPUT behavior:
    - SECURE: Output contains &lt; &gt; &amp; (escaped)
    - INSECURE: Output contains raw < > characters
    """
    xss_payloads = [
        "<script>alert('XSS')</script>",
