import ast
def _run_code_snippet_impl(code):
    """Run code snippet with validation."""
    tree = ast.parse(code)
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom, ast.Call)):
            raise ValueError("Imports and function calls not allowed")
    # Only allow simple assignments
    compiled = compile(tree, '<string>', 'exec')
    safe_globals = {"__builtins__": {}}
    exec(compiled, safe_globals)
    return "executed"

def run_code_snippet_v2(code):
    return _run_code_snippet_impl(code)

