import re

def test_edit_msg_user_mass_assignment():
    """Test mass assignment protection.

    PASS condition: Protected attributes cannot be set
    FAIL condition: Can set admin/role via mass assignment
    """
    class MockUser:
        def __init__(self):
            self.name = "testuser"
            self.email = "test@test.com"
            self.role = "user"
            self.is_admin = False
            self.is_superuser = False

    class MockModel:
        pass

    dangerous_data = {"name": "testuser", "email": "test@test.com",
                      "role": "admin", "is_admin": True, "is_superuser": True}

    try:
        # Try with (user, data) signature first
        result = edit_msg_user(MockUser(), dangerous_data)
    except TypeError:
        try:
            # Try with (model_class, data) signature
            result = edit_msg_user(MockModel, dangerous_data)
        except TypeError:
            # Try generic call
            payload = dangerous_data
            result = edit_msg_user(payload, "test_value")

    if result is not None:
