def _should_be_blocked(link: str) -> bool:
    p = urlparse(link)
    host = p.hostname
    if host is None:
        return False
    host_l = host.lower()

    if host_l in {"localhost", "0.0.0.0"}:
        return True
    if host_l.startswith("127."):
        return True
    if host_l.startswith("192.168."):
        return True
    if host_l == "169.254.169.254" or host_l.startswith("169.254."):
