    try:
        ip = ipaddress.ip_address(host_l)
        if ip.is_loopback or ip.is_link_local or ip.is_private or ip.is_multicast or ip.is_unspecified:
            return True
    except ValueError:
        pass

    if host_l.endswith(".localhost"):
        return True

    return False


