def test_load_template_file_reads_at_most_limit_plus_one_bytes():
    class CountingStream:
        def __init__(self, total_bytes, chunk_size=8192):
            self.remaining = total_bytes
            self.chunk_size = chunk_size
            self.total_read = 0

        def read(self, n=-1):
            if self.remaining <= 0:
                return b""
            if n is None or n < 0:
                to_read = self.remaining
            else:
                to_read = min(self.remaining, n)
            # simulate stream behavior without allocating huge buffers
            out = b"x" * min(to_read, self.chunk_size)
            self.remaining -= len(out)
            self.total_read += len(out)
            return out

