def _is_secretish_string(s: str) -> bool:
    if not isinstance(s, str):
        return False
    v = s.strip()

    # Ignore harmless short tokens
    if len(v) < 8:
        return False

    # Skip obvious placeholders
    if re.fullmatch(r"(?i)(changeme|change_me|replace_me|replace-this|placeholder|example|test|dummy|your[_-]?api[_-]?key)", v):
        return False

    # Common secret patterns / prefixes
    if re.search(r"(?i)\b(aws|secret|token|api[_-]?key|apikey|bearer)\b", v):
        return True
    if re.match(r"(?i)^(sk|rk|pk)_(live|test)_", v):
        return True
    if re.match(r"(?i)^ghp_[A-Za-z0-9]{30,}$", v):
        return True
    if re.match(r"(?i)^AIza[0-9A-Za-z\-_]{20,}$", v):
        return True
    if re.match(r"(?i)^AKIA[0-9A-Z]{16}$", v):
        return True
    if re.match(r"^[A-Za-z0-9_\-]{20,}\.[A-Za-z0-9_\-]{20,}\.[A-Za-z0-9_\-]{10,}$", v):  # JWT-like
        return True

    # High-entropy-ish: long base64/hex blobs
    if re.fullmatch(r"[A-Fa-f0-9]{32,}", v):
        return True
    if re.fullmatch(r"[A-Za-z0-9+/]{32,}={0,2}", v):
        return True

    # If it can be base64-decoded to a long-ish byte string, treat as suspect
    try:
