import inspect
import re
import ast


def _get_source(fn):
    try:
        return inspect.getsource(fn)
    except OSError:
        return ""


def _get_tree(fn):
    src = _get_source(fn)
    try:
        return ast.parse(src)
    except SyntaxError:
        return None


def _is_env_lookup(node):
    # os.environ["X"] / os.environ.get("X") / os.getenv("X")
    if isinstance(node, ast.Subscript):
        v = node.value
        if isinstance(v, ast.Attribute) and v.attr == "environ":
            if isinstance(v.value, ast.Name) and v.value.id == "os":
                return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        if isinstance(node.func.value, ast.Attribute) and node.func.value.attr == "environ":
            if isinstance(node.func.value.value, ast.Name) and node.func.value.value.id == "os":
                if node.func.attr == "get":
                    return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        if isinstance(node.func.value, ast.Name) and node.func.value.id == "os" and node.func.attr == "getenv":
            return True
    return False


def _is_string_literal(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return True
    if isinstance(node, ast.Str):
        return True
    return False


def _const_str_value(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Str):
        return node.s
    return None


def test_no_hardcoded_password_literal_in_connect_to_db(connect_to_db):
    """
    Detect CWE-798: reject hard-coded passwords passed to mysql.connect(...).
    Should pass when password is sourced from env/secret manager, not string literal.
    """
    tree = _get_tree(connect_to_db)
    assert tree is not None, "Unable to parse connect_to_db source for CWE-798 checks"

    bad_literals = []

    class V(ast.NodeVisitor):
        def visit_Call(self, node):
            # check keyword: password=...
            for kw in node.keywords or []:
                if kw.arg == "password" and _is_string_literal(kw.value):
                    bad_literals.append(_const_str_value(kw.value))
            self.generic_visit(node)

    V().visit(tree)

    assert not bad_literals, f"Hard-coded password literal detected: {bad_literals!r}"


