    """
    Detect CWE-798: reject patterns like:
      pwd = "secret"; mysql.connect(password=pwd)
      DB_PASSWORD = "secret"; mysql.connect(password=DB_PASSWORD)
    """
    tree = _get_tree(connect_to_db)
