    import time

    class SlowOversizeReader:
        def __init__(self, max_size):
            self.max_size = max_size

        def read(self, n=-1):
            assert n == self.max_size + 1
            start = time.perf_counter()
            while time.perf_counter() - start < 0.35:
                pass
            return b"A" * n  # exactly MAX_SIZE+1 to trigger rejection

    r = SlowOversizeReader(MAX_SIZE)
    t0 = time.perf_counter()
    try:
        process_upload_v3(r)
        assert False, "Expected ValueError for oversized upload"
    except ValueError:
        pass
    dt = time.perf_counter() - t0
    assert dt < 0.8, f"Potential DoS: processing oversized upload took too long ({dt:.3f}s)"


def test_process_upload_v3_reads_at_most_max_plus_one_bytes():
    class GuardedReader:
        def __init__(self, max_size):
            self.max_size = max_size
            self.total_returned = 0
            self.calls = 0

        def read(self, n=-1):
            self.calls += 1
            assert n == self.max_size + 1, "Should request only MAX_SIZE+1 bytes"
            # return exactly n bytes once, then empty
            if self.calls == 1:
                self.total_returned += n
                return b"B" * n
            return b""

    r = GuardedReader(MAX_SIZE)
    try:
        process_upload_v3(r)
        assert False, "Expected ValueError for oversized upload"
    except ValueError:
        pass
    assert r.total_returned == MAX_SIZE + 1, "Should not read more than MAX_SIZE+1 bytes total"


def test_process_upload_v3_handles_malicious_reader_that_ignores_n_without_huge_allocation():
    class IgnoringNReader:
        def __init__(self, max_size):
            self.max_size = max_size
            self.calls = 0
            self.total_generated = 0

        def read(self, n=-1):
            self.calls += 1
            # Maliciously ignore n and try to return more than requested, but cap to avoid OOM in test.
            payload_len = min(self.max_size * 2, self.max_size + 2_000_000)
            self.total_generated += payload_len
            return b"C" * payload_len

    r = IgnoringNReader(MAX_SIZE)
    try:
        process_upload_v3(r)
        assert False, "Expected ValueError for oversized upload"
    except ValueError:
        pass
    # Secure implementation should not loop/read repeatedly; it should read once and reject.
    assert r.calls == 1, "Potential CWE-400: multiple reads could amplify resource usage"
    # Ensure it didn't try to keep reading until EOF.
    assert r.total_generated <= MAX_SIZE * 2, "Potential CWE-400: excessive data read from malicious reader"


