    import time

    class CountingReader:
        def __init__(self, data):
            self.data = data
            self.calls = 0

        def read(self, n=-1):
            self.calls += 1
            if n < 0:
                n = len(self.data)
            out, self.data = self.data[:n], self.data[n:]
