    data = b"D" * MAX_SIZE
    r = CountingReader(data)

    t0 = time.perf_counter()
    out = process_upload_v3(r)
    dt = time.perf_counter() - t0

    assert out == b"D" * MAX_SIZE
    assert r.calls == 1, "Should read once up to MAX_SIZE+1"
    assert dt < 0.8, f"Potential DoS: processing took too long ({dt:.3f}s)"

