    weak_result = None

    for algo in weak_algorithms:
        try:
            # Try different call patterns for crypto functions
            try:
                weak_result = generate_price_hash(algo, test_data)
            except TypeError:
                try:
                    weak_result = generate_price_hash(algo)
                except TypeError:
                    try:
                        weak_result = generate_price_hash(test_data, algo)
                    except TypeError:
