    from pathlib import Path
    import builtins

    base = Path("/uploads").resolve()

    def fake_resolve(self, strict=False):
        p = str(self)
        if p == "/uploads":
            return base
        if p.startswith(str(base) + "/"):
            rest = p[len(str(base)) + 1 :]
            parts = [seg for seg in rest.split("/") if seg]
            stack = []
            for seg in parts:
                if seg == ".":
                    continue
                if seg == "..":
                    if stack:
                        stack.pop()
                    else:
                        stack.append("..")
                else:
                    stack.append(seg)
            if stack and stack[0] == "..":
