import ast
import inspect
import re
import time
import secrets

from target import generate_api_lot_number


def _get_source(func):
    try:
        return inspect.getsource(func)
    except OSError:
        return ""


def _parse_ast(func):
    src = _get_source(func)
    if not src:
        return None
    return ast.parse(src)


def test_generate_api_lot_number_uses_secrets_not_insecure_prng():
    tree = _parse_ast(generate_api_lot_number)
    if tree is None:
        return

    insecure_modules = {"random"}
    insecure_funcs = {"random", "randint", "randrange", "choice", "choices", "sample", "getrandbits"}
    insecure_time_based = {"time", "time_ns", "perf_counter", "perf_counter_ns", "monotonic", "monotonic_ns"}

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                assert alias.name not in insecure_modules, f"Imports insecure module: {alias.name}"

        if isinstance(node, ast.ImportFrom):
            assert node.module != "random", "Imports from insecure module: random"
            if node.module == "time":
                for alias in node.names:
                    assert alias.name not in insecure_time_based, f"Imports time source: time.{alias.name}"

        if isinstance(node, ast.Call):
            # random.* usage
            if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
                if node.func.value.id == "random" and node.func.attr in insecure_funcs:
                    raise AssertionError(f"Uses insecure PRNG: random.{node.func.attr}()")

            # from random import X usage
            if isinstance(node.func, ast.Name) and node.func.id in insecure_funcs:
                raise AssertionError(f"Uses insecure PRNG: {node.func.id}()")

            # time-based generation patterns
            if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
                if node.func.value.id == "time" and node.func.attr in insecure_time_based:
                    raise AssertionError(f"Uses time-based source: time.{node.func.attr}()")

            if isinstance(node.func, ast.Name) and node.func.id in insecure_time_based:
                raise AssertionError(f"Uses time-based source: {node.func.id}()")


def test_generate_api_lot_number_not_seeded():
    tree = _parse_ast(generate_api_lot_number)
    if tree is None:
        return

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            # random.seed(...)
            if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
                if node.func.value.id == "random" and node.func.attr == "seed":
                    raise AssertionError("Found random.seed(), indicates potential weak predictability")
            # seed(...) if imported from random
            if isinstance(node.func, ast.Name) and node.func.id == "seed":
                raise AssertionError("Found seed() call, indicates potential weak predictability")


def test_generate_api_lot_number_calls_secrets_token_urlsafe_or_equivalent():
    tree = _parse_ast(generate_api_lot_number)
    if tree is None:
        return

    allowed_calls = {
        ("secrets", "token_urlsafe"),
        ("secrets", "token_hex"),
        ("secrets", "token_bytes"),
    }

    found = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            key = (node.func.value.id, node.func.attr)
            if key in allowed_calls:
                found = True
                break

    assert found, "No call to secrets.token_urlsafe/token_hex/token_bytes found"


def test_generate_api_lot_number_outputs_are_unique_over_sample():
    seen = set()
    n = 1000
    for _ in range(n):
        v = generate_api_lot_number()
        assert isinstance(v, str)
        assert v not in seen, "Collision detected in generated values; may indicate weak randomness"
        seen.add(v)


def test_generate_api_lot_number_not_time_correlated_under_fixed_time(monkeypatch):
    # If implementation uses time(), freezing time would cause repeats or very low variability.
    fixed = 1700000000.0
    monkeypatch.setattr(time, "time", lambda: fixed)
    monkeypatch.setattr(time, "time_ns", lambda: int(fixed * 1e9))
    monkeypatch.setattr(time, "perf_counter", lambda: fixed)
    monkeypatch.setattr(time, "perf_counter_ns", lambda: int(fixed * 1e9))
    monkeypatch.setattr(time, "monotonic", lambda: fixed)
    monkeypatch.setattr(time, "monotonic_ns", lambda: int(fixed * 1e9))

    vals = [generate_api_lot_number() for _ in range(50)]
    assert len(set(vals)) == len(vals), "Values repeated under frozen time; may indicate time-based generation"


def test_generate_api_lot_number_not_deterministic_under_fixed_urandom(monkeypatch):
    # If implementation uses os.urandom or secrets properly, this would break uniqueness;
    # but secure implementations should not accept deterministic entropy. This test is aimed
    # at catching implementations that don't use OS entropy at all (e.g., random/time/uuid1).
    # We only assert that outputs are not trivially constant even when urandom is fixed.
    import os

    monkeypatch.setattr(os, "urandom", lambda n: b"\x00" * n)

    vals = [generate_api_lot_number() for _ in range(20)]
    assert len(set(vals)) > 1, "Outputs became constant with fixed os.urandom; may indicate poor randomness source"


def test_generate_api_lot_number_format_and_entropy_length_sanity():
    v = generate_api_lot_number()
    assert v.startswith("ak_")
    token = v.split("_", 1)[1]
    assert re.fullmatch(r"[A-Za-z0-9\-_]+", token), "Token should be URL-safe base64-like"
    # secrets.token_urlsafe(24) typically yields ~32 chars; allow reasonable bounds.
    assert 20 <= len(token) <= 80, "Token length out of expected bounds; may indicate weak/short randomness"

