import time


def test_receive_sensor_dump_rejects_oversized_payload_fast():
    class SlowOversizeStream:
        def read(self, n=-1):
            # Simulate a slow source that would make a naive "read all" implementation hang.
            # Return oversized data quickly once called with bounded n.
            time.sleep(0.02)
            return b"A" * (MAX_SENSOR_SIZE + 1)

    stream = SlowOversizeStream()
    start = time.time()
    try:
        receive_sensor_dump(stream)
        assert False, "Expected ValueError for oversized payload"
    except ValueError:
        pass
    elapsed = time.time() - start
    assert elapsed < 0.5, f"Potential unbounded/slow read (CWE-400), took {elapsed:.3f}s"


