    class SpyStream:
        def __init__(self):
            self.calls = []

        def read(self, n=-1):
            self.calls.append(n)
            # If implementation tries to read unbounded (n < 0), return huge data to emulate blow-up.
            if n is None or n < 0:
                return b"X" * (MAX_SENSOR_SIZE + 10)
            return b"Y" * min(n, MAX_SENSOR_SIZE + 1)

