    import time

    class SlowStream:
        def __init__(self, total):
            self.remaining = total

        def read(self, n=-1):
            # Returns promptly; if implementation loops repeatedly, it will add delay each iteration.
            time.sleep(0.01)
            if self.remaining <= 0:
                return b""
            k = min(self.remaining, max(0, n if n >= 0 else self.remaining))
            self.remaining -= k
            return b"A" * k

